 "content": "def transform(grid):
    # Draw the two colored diagonal beams represented by the pair of 0s
    # and the pair of 2s, extending them to the grid boundary.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    colors = {}
    for r in range(h):
        for c in range(w):
            colors.setdefault(grid[r][c], []).append((r, c))
    background = max(colors, key=lambda color: len(colors[color]))
    for color, pts in colors.items():
        if color == background or len(pts) < 2:
            continue
        # Two matching diagonal points define a line; preserve the source cells
        # of other colors and paint only background cells along that line.
        found = None
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i+1:]:
                dr, dc = r2-r1, c2-c1
                if abs(dr) == abs(dc) and dr != 0:
                    g = abs(dr)
                    sr, sc = dr//g, dc//g
                    found = (r1, c1, sr, sc)
