    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Extend only the diagonal color path that forms the longest straight run.
    # A pair of adjacent colors can be part of a small motif (as in demo 1),
    # whereas the intended beam is the repeated line motif in the scene.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    candidates = []
    for color, n in counts.items():
        if color == bg:
            continue
        for dr, dc in ((1, 1), (1, -1)):
            for r in range(h):
                for c in range(w):
                    if grid[r][c] != color:
                        continue
                    pr, pc = r-dr, c-dc
                    if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                        continue
                    run=[]; rr,cc=r,c
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                        run.append((rr,cc)); rr+=dr; cc+=dc
                    if len(run) >= 2:
                        candidates.append((len(run), color, dr, dc, run))
    if not candidates:
        return out
    # Grow runs belonging to color(s) of maximum length, matching the distinct
    # full-length beam rather than incidental short diagonal pairs.
    max_len = max(x[0] for x in candidates)
    for _, color, dr, dc, run in candidates:
        if len(run) != max_len:
            continue
        for rr,cc,sr,sc in ((run[0][0]-dr,run[0][1]-dc,-dr,-dc),
                            (run[-1][0]+dr,run[-1][1]+dc,dr,dc)):
